        regex = re.compile(pattern, flags)
    except Exception:
        # Fallback if invalid regex
        regex = re.compile(re.escape(pattern), flags)

    matches_by_file = {}

    for base_path in paths:
        if os.path.isfile(base_path):
            files_to_check = [base_path]
        else:
