import sys, os, re, subprocess
import curses

def parse_args():
    args = sys.argv[1:]
    options_with_value = {
        "--editor", "--custom-command", "--theme", "-g", "--glob",
        "-t", "--type", "-T", "--type-not", "--context-viewer",
        "--sort", "--sortr"
    }

    parsed = {
        "editor": None,
        "custom_command": os.environ.get("IGREP_CUSTOM_EDITOR"),
        "pattern": None,
        "paths": [],
        "ignore_case": False,
        "hidden": False
    }

    i = 0
    while i < len(args):
        arg = args[i]
        if arg in options_with_value:
            if arg == "--editor":
                parsed["editor"] = args[i+1]
            elif arg == "--custom-command":
                parsed["custom_command"] = args[i+1]
            i += 2
            continue
        elif arg.startswith("-"):
            if arg in ["-i", "--ignore-case"]:
                parsed["ignore_case"] = True
            elif arg in ["-.", "--hidden"]:
                parsed["hidden"] = True
            i += 1
            continue
        else:
            if parsed["pattern"] is None:
                parsed["pattern"] = arg
            else:
                parsed["paths"].append(arg)
            i += 1

    if not parsed["paths"]:
        parsed["paths"] = ["."]

    return parsed

def do_search(pattern, paths, ignore_case=False, hidden=False):
    flags = 0
    if ignore_case:
        flags |= re.IGNORECASE
    try:
        regex = re.compile(pattern, flags)
    except:
        regex = re.compile(re.escape(pattern), flags)

    matches_by_file = {}
    for base_path in paths:
        if os.path.isfile(base_path):
            files_to_check = [base_path]
        else:
            files_to_check = []
            for root, dirs, files in os.walk(base_path):
                if not hidden:
                    dirs[:] = [d for d in dirs if not d.startswith('.')]
                for f in files:
                    if not hidden and f.startswith('.'):
                        continue
                    files_to_check.append(os.path.join(root, f))

        for filepath in files_to_check:
            try:
                with open(filepath, 'r', encoding='utf-8') as f:
                    lines = f.readlines()
                file_matches = []
                for line_idx, line in enumerate(lines):
                    for m in regex.finditer(line):
                        file_matches.append({
                            'line_no': line_idx + 1,
                            'line': line.rstrip('\n'),
                            'start': m.start(),
                            'end': m.end()
                        })
                if file_matches:
                    clean_path = filepath
                    if clean_path.startswith("./") and clean_path != "./":
                        clean_path = clean_path[2:]
                    matches_by_file[clean_path] = file_matches
            except:
                pass
    return matches_by_file

def run_tui(stdscr, matches_by_file, parsed):
    curses.start_color()
    curses.use_default_colors()
    curses.init_pair(1, curses.COLOR_MAGENTA, -1)
    curses.init_pair(2, curses.COLOR_GREEN, -1)
    curses.init_pair(3, curses.COLOR_RED, -1)
    curses.init_pair(4, curses.COLOR_BLACK, curses.COLOR_GREEN)
    curses.init_pair(5, curses.COLOR_WHITE, curses.COLOR_BLACK) # fallback for selected

    curses.curs_set(0)
    stdscr.nodelay(False)

    display_items = []
    for filepath, matches in sorted(matches_by_file.items()):
        display_items.append(('file', filepath))
        for m in matches:
            display_items.append(('match', filepath, m))

    selectable_indices = [i for i, item in enumerate(display_items) if item[0] == 'match']

    if not selectable_indices:
        return None

    sel_list_idx = 0
    offset_y = 0

    while True:
        h, w = stdscr.getmaxyx()
        stdscr.clear()

        # Draw box
        try:
            stdscr.addstr(0, 0, '╭' + '─' * (w-2) + '╮')
            for y in range(1, h-2):
                stdscr.addstr(y, 0, '│')
                stdscr.addstr(y, w-1, '│')
            stdscr.addstr(h-2, 0, '╰' + '─' * (w-2) + '╯')
        except:
            pass

        content_height = h - 3
        selected_item_idx = selectable_indices[sel_list_idx]

        for i in range(content_height):
            item_idx = offset_y + i
            if item_idx >= len(display_items):
                break

            item = display_items[item_idx]
            y = 1 + i

            try:
                if item[0] == 'file':
                    stdscr.addstr(y, 1, item[1][:w-2], curses.color_pair(1))
                else:
                    _, filepath, m = item
                    prefix = f" {m['line_no']}: "
                    full_text = (prefix + m['line'])[:w-2]

                    if item_idx == selected_item_idx:
                        stdscr.addstr(y, 1, full_text.ljust(w-2), curses.A_REVERSE)
                    else:
                        stdscr.addstr(y, 1, prefix, curses.color_pair(2))
                        rem_len = w - 2 - len(prefix)
                        if rem_len > 0:
                            line_text = m['line'][:rem_len]
                            start = min(m['start'], rem_len)
                            end = min(m['end'], rem_len)

                            if start > 0:
                                stdscr.addstr(y, 1 + len(prefix), line_text[:start])
                            if end > start:
                                stdscr.addstr(y, 1 + len(prefix) + start, line_text[start:end], curses.color_pair(3))
                            if end < len(line_text):
                                stdscr.addstr(y, 1 + len(prefix) + end, line_text[end:])
            except:
                pass

        # Status bar
        total_matches = len(selectable_indices)
        total_files = len(matches_by_file)
        # Format: "  FINISHED   Found X matches in Y files." on green bg for FINISHED, rest on normal bg
        try:
            stdscr.addstr(h-1, 0, "  FINISHED  ", curses.color_pair(4) | curses.A_BOLD)
            status_text = f" Found {total_matches} match{'es' if total_matches>1 else ''} in {total_files} file{'s' if total_files>1 else ''}. "
            status_text2 = f"| {sel_list_idx+1}/{total_matches} "
            spaces = w - 12 - len(status_text) - len(status_text2)
            if spaces < 0: spaces = 0
            stdscr.addstr(h-1, 12, status_text + " " * spaces + status_text2)
        except:
            pass

        stdscr.refresh()

        ch = stdscr.getch()
        if ch == ord('q') or ch == 27: # q or ESC
            return None
        elif ch in [ord('j'), curses.KEY_DOWN]:
            if sel_list_idx < len(selectable_indices) - 1:
                sel_list_idx += 1
        elif ch in [ord('k'), curses.KEY_UP]:
            if sel_list_idx > 0:
                sel_list_idx -= 1
        elif ch == ord('\n') or ch == curses.KEY_ENTER:
            return display_items[selected_item_idx]

        # Update offset
        selected_item_idx = selectable_indices[sel_list_idx]
        if selected_item_idx < offset_y:
            offset_y = selected_item_idx
        elif selected_item_idx >= offset_y + content_height:
            offset_y = selected_item_idx - content_height + 1

def main():
    if "--help" in sys.argv or "-h" in sys.argv:
        with open("help.txt") as f:
            print(f.read(), end="")
        sys.exit(0)
    if "--version" in sys.argv or "-V" in sys.argv:
        with open("version.txt") as f:
            print(f.read(), end="")
        sys.exit(0)
    if "--type-list" in sys.argv:
        with open("type_list.txt") as f:
            print(f.read(), end="")
        sys.exit(0)

    parsed = parse_args()
    matches = do_search(parsed["pattern"], parsed["paths"], parsed["ignore_case"], parsed["hidden"])

    if not matches:
        sys.exit(0)

    selected = curses.wrapper(run_tui, matches, parsed)

    if selected:
        _, filepath, m = selected
        line_no = m['line_no']

        # open editor
        editor = parsed.get("editor") or os.environ.get("IGREP_EDITOR") or os.environ.get("VISUAL") or os.environ.get("EDITOR") or "vim"
        custom_cmd = parsed.get("custom_command")

        if custom_cmd:
            cmd = custom_cmd.replace("{file_name}", filepath).replace("{line_number}", str(line_no))
            subprocess.call(cmd, shell=True)
        else:
            # typical editors support +line file
            subprocess.call([editor, f"+{line_no}", filepath])

if __name__ == "__main__":
    main()
